package org.anon.companion;
import android.content.*;
import android.os.Build;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.zip.*;

/** Private, bounded diagnostics. All disk access is serialized in the main process. */
public final class Diagnostics {
 public static final int LIMIT=512*1024;
 private static final Object LOCK=new Object();
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("diagnostics",0);}
 public static boolean active(Context c){return prefs(c).getBoolean("enabled",false)&&System.currentTimeMillis()<prefs(c).getLong("until",0);}
 public static String token(Context c){return active(c)?prefs(c).getString("session",""):"";}
 public static long until(Context c){return prefs(c).getLong("until",0);}
 public static int received(Context c){return prefs(c).getInt("received",0);}
 private static File dir(Context c){File f=new File(c.getFilesDir(),"diagnostics");f.mkdirs();return f;}
 public static void start(Context c)throws IOException {synchronized(LOCK){clearFiles(c);prefs(c).edit().putBoolean("enabled",true).putString("session",UUID.randomUUID().toString()).putLong("until",System.currentTimeMillis()+15*60*1000).putInt("received",0).putInt("ack",0).putLong("lastPacket",0).commit();event(c,"helper","recording_started",null);}publish(c);}
 public static void stop(Context c){event(c,"helper","recording_stopped",null);prefs(c).edit().putBoolean("enabled",false).commit();publish(c);}
 private static void clearFiles(Context c)throws IOException{for(String name:new String[]{"events.jsonl","previous.jsonl"}){File f=new File(dir(c),name);if(f.exists()&&!f.delete())throw new IOException("Cannot clear diagnostics");}}
 public static void clear(Context c)throws IOException{synchronized(LOCK){prefs(c).edit().putBoolean("enabled",false).putInt("received",0).commit();clearFiles(c);}publish(c);}
 public static String clean(String value){if(value==null)return "";String s=value.replaceAll("(?i)(?:https?://|file:|content:|blob:|data:)[^\\s]+","[resource]").replaceAll("[A-Za-z]:[\\\\/][^\\s]+","[path]");return s.length()>500?s.substring(0,500):s;}
 public static boolean event(Context c,String source,String kind,JSONObject details){if(!active(c))return false;try{JSONObject e=new JSONObject().put("at",System.currentTimeMillis()).put("source",source).put("event",clean(kind));if(details!=null)e.put("details",details);return append(c,e);}catch(Exception ignored){return false;}}
 private static boolean append(Context c,JSONObject e)throws IOException {synchronized(LOCK){byte[] bytes=(e.toString()+"\n").getBytes("UTF-8");if(bytes.length>8192)return false;File file=new File(dir(c),"events.jsonl");if(file.length()+bytes.length>LIMIT/2){File old=new File(dir(c),"previous.jsonl");if(old.exists()&&!old.delete())return false;if(file.exists()&&!file.renameTo(old))return false;}try(FileOutputStream os=new FileOutputStream(file,true)){os.write(bytes);}return true;}}
 public static void receive(Context c,String session,String payload){if(!active(c)||!token(c).equals(session)||payload==null||payload.length()>12000)return;synchronized(LOCK){long now=System.currentTimeMillis(),last=prefs(c).getLong("lastPacket",0);if(now-last<400)return;prefs(c).edit().putLong("lastPacket",now).apply();try{JSONObject packet=new JSONObject(payload);int sequence=packet.getInt("seq");if(sequence<=prefs(c).getInt("ack",0)){publish(c);return;}JSONArray batch=packet.getJSONArray("events");if(batch.length()>16)return;for(int n=0;n<batch.length();n++){JSONObject input=batch.getJSONObject(n),details=new JSONObject(),fields=input.optJSONObject("details");if(fields!=null)for(String key:new String[]{"character","outfit","slot","secondCharacter","secondOutfit","fps","duo","page","control","action","expression","voiceClip","targetFPS","measuredFPS","error","stage","count","bridge","durationMs","resourcesUnloaded","value","modelScale","modelX","modelY","secondScale","secondX","secondY","backgroundMode","backgroundImage","uiTheme","hostPaused","renderWorkMS","renderResolution","qualityScale"})if(fields.has(key)){Object v=fields.get(key);if(v instanceof Number||v instanceof Boolean)details.put(key,v);else details.put(key,clean(String.valueOf(v)));}details.put("clientAt",input.optLong("at",0)).put("batchSeq",sequence).put("batchIndex",n);if(!event(c,"wallpaper",input.optString("event","unknown"),details))return;}prefs(c).edit().putInt("received",received(c)+batch.length()).putInt("ack",sequence).apply();publish(c);}catch(Exception ignored){}}}
 public static void publish(Context c){Intent i=new Intent("org.anon.companion.DIAGNOSTIC_STATE").putExtra("enabled",active(c)?1:0).putExtra("session",token(c)).putExtra("until",String.valueOf(until(c))).putExtra("received",received(c)).putExtra("ack",prefs(c).getInt("ack",0));for(String pkg:new String[]{"com.xiaomi.subscreencenter","com.android.thememanager"})c.sendBroadcast(new Intent(i).setPackage(pkg));}
 public static JSONObject environment(Context c)throws JSONException{return new JSONObject().put("schema",1).put("helper",RuntimeReceiver.versionName(c,c.getPackageName())).put("model",Build.MODEL).put("manufacturer",Build.MANUFACTURER).put("androidAPI",Build.VERSION.SDK_INT).put("systemBuild",Build.VERSION.INCREMENTAL).put("rearHost",RuntimeReceiver.versionName(c,"com.xiaomi.subscreencenter")).put("webview",RuntimeReceiver.webVersion()).put("wallpaperVersion","ANON 52").put("receivedWallpaperEvents",received(c)).put("recordingActive",active(c));}
 public static File export(Context c,JSONObject feedback,android.net.Uri screenshot)throws Exception{synchronized(LOCK){File folder=new File(c.getCacheDir(),"diagnostic-exports");folder.mkdirs();File target=new File(folder,"report-"+System.currentTimeMillis()+".zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(target))){write(zip,"environment.json",environment(c).toString(2).getBytes("UTF-8"));write(zip,"feedback.json",feedback.toString(2).getBytes("UTF-8"));write(zip,"README.txt",("本包仅包含本应用诊断；不是系统完整日志。\n默认不含账号、设备唯一标识、相机、音频或姓名框文字。反馈文字及手动附件由用户提供，请分享前检查。\n已收背屏事件："+received(c)+"。为0时未证明日志链路接通。\n").getBytes("UTF-8"));for(String name:new String[]{"previous.jsonl","events.jsonl"}){File f=new File(dir(c),name);if(f.exists())try(InputStream in=new FileInputStream(f)){copy(zip,name,in,LIMIT/2);}}if(screenshot!=null){String mime=c.getContentResolver().getType(screenshot);if(mime==null||!mime.startsWith("image/"))throw new IOException("请选择图片附件");try(InputStream in=c.getContentResolver().openInputStream(screenshot)){copy(zip,"user-screenshot"+(mime.contains("png")?".png":mime.contains("webp")?".webp":".jpg"),in,2*1024*1024);}}}catch(Exception e){target.delete();throw e;}File[] files=folder.listFiles((d,n)->n.matches("report-[0-9]+\\.zip"));if(files!=null){Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(int i=3;i<files.length;i++)files[i].delete();}return target;}}
 private static void write(ZipOutputStream z,String name,byte[] data)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(data);z.closeEntry();}
 private static void copy(ZipOutputStream z,String name,InputStream in,int max)throws IOException{if(in==null)throw new IOException("无法读取附件");z.putNextEntry(new ZipEntry(name));byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("图片附件不能超过2 MiB");z.write(b,0,n);}z.closeEntry();}
}
